#include <bits/stdc++.h>
using namespace std;
struct DSU{vector<int>p,s;DSU(int n):p(n),s(n,1){iota(p.begin(),p.end(),0);}int f(int x){return p[x]==x?x:p[x]=f(p[x]);}void u(int a,int b){a=f(a);b=f(b);if(a!=b){if(s[a]<s[b])swap(a,b);p[b]=a;s[a]+=s[b];}}};
int main(){ios::sync_with_stdio(false);cin.tie(nullptr);int T;cin>>T;while(T--){int n,m,q;cin>>n>>m>>q;vector<string>g(n);for(auto &x:g)cin>>x;DSU d(2*n*m);auto id=[&](int r,int c,int mode){return mode*n*m+r*m+c;};for(int r=0;r<n;r++)for(int c=0;c<m;c++){for(int mode=0;mode<2;mode++){char need=mode?'R':'B';if(g[r][c]!='.'&&g[r][c]!=need)continue;if(r+1<n&&(g[r+1][c]=='.'||g[r+1][c]==need))d.u(id(r,c,mode),id(r+1,c,mode));if(c+1<m&&(g[r][c+1]=='.'||g[r][c+1]==need))d.u(id(r,c,mode),id(r,c+1,mode));}if(g[r][c]=='.')d.u(id(r,c,0),id(r,c,1));}while(q--){int a,b,c,e;cin>>a>>b>>c>>e;bool ok=false;for(int mode=0;mode<2;mode++){char need=mode?'R':'B';if(g[c][e]=='.'||g[c][e]==need)if(d.f(id(a,b,0))==d.f(id(c,e,mode)))ok=true;}cout<<(ok?"YES":"NO")<<'\n';}}}
